#define PI 3.14159265359
#define TWO_PI 6.28318530718
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    vec2 m = abs(2.0*(iMouse.xy-iResolution.xy)/iResolution.xy);

    vec3 color;
    int N = iMouse.z >0.1? clamp(3, 16, int(floor((m.x+m.y)*3.))+1):3 ;

    float r = length(st);

    float a = atan(st.x, st.y) + PI;


    float b = TWO_PI / float(N);

    float AA = 6.0 / iResolution.y;

    //thanks to http://thndl.com/square-shaped-shaders.html

    float d = cos(floor(0.5 + a / b) * b - a) * length(st);



    color = vec3(1. - smoothstep(0.3, 0.3 + AA, d));


    fragColor = vec4(color, 1.0f);
}
